UPDATE email_sequences SET steps = '[{"type": "send_email", "subject": "Your 5-Day Immunity Starter is here \ud83d\udee1\ufe0f", "from_name": "Vanto Zazi", "content": "<p>Hey {{first_name}},</p>\n<p>Here''s the free guide you asked for \u2014 <strong>5-Day Immunity Starter</strong>. No supplements required.</p>\n<p style=\"margin: 24px 0;\">\n  <a href=\"https://kit-clone-dashboard.lovable.app/lead-magnets/5-Day-Immunity-Starter-v1.pdf\" style=\"display:inline-block; background:#1a3a8a; color:#fff; padding:14px 24px; border-radius:8px; text-decoration:none; font-weight:600;\">\ud83d\udce5 Download the Immunity Reset PDF</a>\n</p>\n<p>Tomorrow I''ll ask you one quick question. No pitch.</p>\n<p>\u2014 Vanto</p>"}, {"type": "wait", "duration_hours": 24}, {"type": "send_email", "subject": "Quick question about your immunity", "from_name": "Vanto Zazi", "content": "<p>Hey {{first_name}},</p>\n<p>Hope you had a chance to skim the guide. Quick one \u2014</p>\n<p><strong>What''s been hitting you hardest lately?</strong></p>\n<ul>\n  <li>Catching every bug going around</li>\n  <li>Feeling run-down even after rest</li>\n  <li>Recovery taking longer than it used to</li>\n  <li>Something else</li>\n</ul>\n<p>Just hit reply and tell me. I read every one.</p>\n<p>\u2014 Vanto</p>"}, {"type": "wait", "duration_hours": 48}, {"type": "send_email", "subject": "The 10-minute morning habit most people skip", "from_name": "Vanto Zazi", "content": "<p>Hey {{first_name}},</p>\n<p>Most people try to fix immunity with supplements alone. The real foundation is what you do in the <strong>first 30 minutes of the day</strong>.</p>\n<blockquote style=\"border-left:3px solid #1a3a8a; padding:8px 16px; margin:16px 0; background:#f7f8fc;\">\n  <strong>Get 10 minutes of morning sunlight, before screens.</strong> Direct light on your eyes (no sunglasses) regulates cortisol and gives your immune system its strongest signal of the day.\n</blockquote>\n<p>Try it today and tomorrow. Let me know how it goes.</p>\n<p>\u2014 Vanto</p>"}, {"type": "wait", "duration_hours": 48}, {"type": "send_email", "subject": "What Thandi did when she kept getting sick", "from_name": "Vanto Zazi", "content": "<p>Hey {{first_name}},</p>\n<p>One reader tried the routine for a week. They told us:</p>\n<blockquote style=\"border-left:3px solid #1a3a8a; padding:8px 16px; margin:16px 0; background:#f7f8fc; font-style:italic;\">\n  \"I''m not catching every cold in the office anymore \u2014 and when I do feel something, it passes in a day instead of a week.\"\n</blockquote>\n<p>That''s the goal: a steadier baseline, not a quick fix.</p>\n<p>If you want to go further, tomorrow I''ll share the options some readers add on top.</p>\n<p>\u2014 Vanto</p>"}, {"type": "wait", "duration_hours": 48}, {"type": "send_email", "subject": "One more option (only if you want it)", "from_name": "Vanto Zazi", "content": "<p>Hey {{first_name}},</p>\n<p>Some readers add a small lozenge from the APLGO Immunity family to their daily routine. Plant-based blends, not medication \u2014 just one more tool.</p>\n<p>If you''re curious, here are the options:</p>\n<p style=\"margin: 16px 0;\">\n  <a href=\"https://onlinecourseformlm.com/shop/grw?ref={{ref_code}}\" style=\"display:inline-block; background:#1a3a8a; color:#fff; padding:12px 22px; border-radius:8px; text-decoration:none; font-weight:600;\">\ud83c\udf3f GRW \u2014 daily immune support</a>\n</p>\n<p style=\"margin: 16px 0;\">\n  <a href=\"https://onlinecourseformlm.com/shop/gts?ref={{ref_code}}\" style=\"display:inline-block; background:#1a3a8a; color:#fff; padding:12px 22px; border-radius:8px; text-decoration:none; font-weight:600;\">\ud83c\udf3f GTS \u2014 everyday wellness</a>\n</p>\n<p>If not, no problem \u2014 keep using the guide. Either way, <strong>look after yourself</strong>.</p>\n<p>\u2014 Vanto</p>"}]'::jsonb, updated_at = now() WHERE id = '462db47a-7d6e-47f1-92d2-640e13683cbd';
UPDATE email_sequences SET steps = '[{"type": "send_email", "subject": "Your 5-Day Energy & Focus Reset is here \u26a1", "from_name": "Vanto Zazi", "content": "<p>Hey {{first_name}},</p>\n<p>Here''s the free guide you asked for \u2014 <strong>5-Day Energy & Focus Reset</strong>. No supplements required.</p>\n<p style=\"margin: 24px 0;\">\n  <a href=\"https://kit-clone-dashboard.lovable.app/lead-magnets/5-Day-Energy-and-Focus-Reset-v1.pdf\" style=\"display:inline-block; background:#1a3a8a; color:#fff; padding:14px 24px; border-radius:8px; text-decoration:none; font-weight:600;\">\ud83d\udce5 Download the Energy Reset PDF</a>\n</p>\n<p>Tomorrow I''ll ask you one quick question. No pitch.</p>\n<p>\u2014 Vanto</p>"}, {"type": "wait", "duration_hours": 24}, {"type": "send_email", "subject": "Quick question about your energy", "from_name": "Vanto Zazi", "content": "<p>Hey {{first_name}},</p>\n<p>Hope you had a chance to skim the guide. Quick one \u2014</p>\n<p><strong>What hits you hardest in the day?</strong></p>\n<ul>\n  <li>Morning fog \u2014 hard to start</li>\n  <li>2\u20133pm crash that wipes out the afternoon</li>\n  <li>Mental fatigue by 5pm with hours of work left</li>\n  <li>Something else</li>\n</ul>\n<p>Just hit reply and tell me. I read every one.</p>\n<p>\u2014 Vanto</p>"}, {"type": "wait", "duration_hours": 48}, {"type": "send_email", "subject": "The 2 PM crash isn''t about coffee", "from_name": "Vanto Zazi", "content": "<p>Hey {{first_name}},</p>\n<p>Most people try to fix the afternoon crash with more caffeine. The real lever is what you do <strong>between 11am and 1pm</strong>.</p>\n<blockquote style=\"border-left:3px solid #1a3a8a; padding:8px 16px; margin:16px 0; background:#f7f8fc;\">\n  <strong>Eat protein before carbs at lunch.</strong> Same plate \u2014 just protein and fibre first, starches last. Blunts the post-lunch insulin spike that causes the 2pm crash.\n</blockquote>\n<p>Try it today and tomorrow. Let me know how it goes.</p>\n<p>\u2014 Vanto</p>"}, {"type": "wait", "duration_hours": 48}, {"type": "send_email", "subject": "How Sipho got his afternoons back", "from_name": "Vanto Zazi", "content": "<p>Hey {{first_name}},</p>\n<p>One reader tried the routine for a week. They told us:</p>\n<blockquote style=\"border-left:3px solid #1a3a8a; padding:8px 16px; margin:16px 0; background:#f7f8fc; font-style:italic;\">\n  \"I''m not relying on a 3pm coffee anymore \u2014 and I''m getting more done between 2 and 5 than I used to do all morning.\"\n</blockquote>\n<p>That''s the goal: steady focus, not a chemical rollercoaster.</p>\n<p>If you want to go further, tomorrow I''ll share the options some readers add on top.</p>\n<p>\u2014 Vanto</p>"}, {"type": "wait", "duration_hours": 48}, {"type": "send_email", "subject": "One more option (only if you want it)", "from_name": "Vanto Zazi", "content": "<p>Hey {{first_name}},</p>\n<p>Some readers add a small lozenge from the APLGO Energy family to their daily routine. Plant-based blends, not medication \u2014 just one more tool.</p>\n<p>If you''re curious, here are the options:</p>\n<p style=\"margin: 16px 0;\">\n  <a href=\"https://onlinecourseformlm.com/shop/sld?ref={{ref_code}}\" style=\"display:inline-block; background:#1a3a8a; color:#fff; padding:12px 22px; border-radius:8px; text-decoration:none; font-weight:600;\">\ud83c\udf3f SLD \u2014 natural energy & focus</a>\n</p>\n<p style=\"margin: 16px 0;\">\n  <a href=\"https://onlinecourseformlm.com/shop/stp?ref={{ref_code}}\" style=\"display:inline-block; background:#1a3a8a; color:#fff; padding:12px 22px; border-radius:8px; text-decoration:none; font-weight:600;\">\ud83c\udf3f STP \u2014 performance support</a>\n</p>\n<p>If not, no problem \u2014 keep using the guide. Either way, <strong>look after yourself</strong>.</p>\n<p>\u2014 Vanto</p>"}]'::jsonb, updated_at = now() WHERE id = 'd9f83f1f-eb64-47fd-ae87-26c65821e4c9';
UPDATE email_sequences SET steps = '[{"type": "send_email", "subject": "Your 5-Day Detox & Cleanse is here \ud83c\udf3f", "from_name": "Vanto Zazi", "content": "<p>Hey {{first_name}},</p>\n<p>Here''s the free guide you asked for \u2014 <strong>5-Day Detox & Cleanse</strong>. No supplements required.</p>\n<p style=\"margin: 24px 0;\">\n  <a href=\"https://kit-clone-dashboard.lovable.app/lead-magnets/5-Day-Detox-and-Cleanse-v1.pdf\" style=\"display:inline-block; background:#1a3a8a; color:#fff; padding:14px 24px; border-radius:8px; text-decoration:none; font-weight:600;\">\ud83d\udce5 Download the Detox Reset PDF</a>\n</p>\n<p>Tomorrow I''ll ask you one quick question. No pitch.</p>\n<p>\u2014 Vanto</p>"}, {"type": "wait", "duration_hours": 24}, {"type": "send_email", "subject": "Quick question about your detox", "from_name": "Vanto Zazi", "content": "<p>Hey {{first_name}},</p>\n<p>Hope you had a chance to skim the guide. Quick one \u2014</p>\n<p><strong>What''s been weighing you down?</strong></p>\n<ul>\n  <li>Bloating or heaviness after meals</li>\n  <li>Sluggish digestion that throws off the day</li>\n  <li>Skin or breath that says my system is overloaded</li>\n  <li>Something else</li>\n</ul>\n<p>Just hit reply and tell me. I read every one.</p>\n<p>\u2014 Vanto</p>"}, {"type": "wait", "duration_hours": 48}, {"type": "send_email", "subject": "The cleanse trick most people get wrong", "from_name": "Vanto Zazi", "content": "<p>Hey {{first_name}},</p>\n<p>Most people think a cleanse means cutting everything out. The real lever is <strong>what you add in the first hour of the day</strong>.</p>\n<blockquote style=\"border-left:3px solid #1a3a8a; padding:8px 16px; margin:16px 0; background:#f7f8fc;\">\n  <strong>500ml of warm water with lemon, before coffee.</strong> Wakes up the digestive tract gently, supports the liver''s morning detox window, and cuts mid-morning bloat.\n</blockquote>\n<p>Try it today and tomorrow. Let me know how it goes.</p>\n<p>\u2014 Vanto</p>"}, {"type": "wait", "duration_hours": 48}, {"type": "send_email", "subject": "What Lerato felt after one week", "from_name": "Vanto Zazi", "content": "<p>Hey {{first_name}},</p>\n<p>One reader tried the routine for a week. They told us:</p>\n<blockquote style=\"border-left:3px solid #1a3a8a; padding:8px 16px; margin:16px 0; background:#f7f8fc; font-style:italic;\">\n  \"I''m not bloated by lunchtime anymore \u2014 and my skin actually changed in 5 days.\"\n</blockquote>\n<p>That''s the goal: a system that''s clearing properly, every day \u2014 not a once-a-month reset.</p>\n<p>If you want to go further, tomorrow I''ll share the options some readers add on top.</p>\n<p>\u2014 Vanto</p>"}, {"type": "wait", "duration_hours": 48}, {"type": "send_email", "subject": "One more option (only if you want it)", "from_name": "Vanto Zazi", "content": "<p>Hey {{first_name}},</p>\n<p>Some readers add a small lozenge from the APLGO Detox family to their daily routine. Plant-based blends, not medication \u2014 just one more tool.</p>\n<p>If you''re curious, here are the options:</p>\n<p style=\"margin: 16px 0;\">\n  <a href=\"https://onlinecourseformlm.com/shop/pwr-lemon?ref={{ref_code}}\" style=\"display:inline-block; background:#1a3a8a; color:#fff; padding:12px 22px; border-radius:8px; text-decoration:none; font-weight:600;\">\ud83c\udf3f PWR Lemon \u2014 daily cleanse & balance</a>\n</p>\n<p style=\"margin: 16px 0;\">\n  <a href=\"https://onlinecourseformlm.com/shop/pwr-apricot?ref={{ref_code}}\" style=\"display:inline-block; background:#1a3a8a; color:#fff; padding:12px 22px; border-radius:8px; text-decoration:none; font-weight:600;\">\ud83c\udf3f PWR Apricot \u2014 gentle detox support</a>\n</p>\n<p>If not, no problem \u2014 keep using the guide. Either way, <strong>look after yourself</strong>.</p>\n<p>\u2014 Vanto</p>"}]'::jsonb, updated_at = now() WHERE id = '5738da89-3a6e-45e9-8db9-4aadb48e507f';